function(container, apiUrl, tables) {
  // 業務ロジックモジュールのインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aiLogic || {};

  // 初期化処理
  const today = new Date().toISOString().split('T')[0];
  const oneYearAgo = new Date();
  oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);
  const oneYearAgoStr = oneYearAgo.toISOString().split('T')[0];

  // デフォルト値設定
  const learningStartDate = container.querySelector('#learning-start-date');
  const learningEndDate = container.querySelector('#learning-end-date');
  const predictionStartDate = container.querySelector('#prediction-start-date');
  const predictionEndDate = container.querySelector('#prediction-end-date');

  if (learningStartDate) learningStartDate.value = oneYearAgoStr;
  if (learningEndDate) learningEndDate.value = today;

  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowStr = tomorrow.toISOString().split('T')[0];
  if (predictionStartDate) predictionStartDate.value = tomorrowStr;

  const nextWeek = new Date();
  nextWeek.setDate(nextWeek.getDate() + 7);
  const nextWeekStr = nextWeek.toISOString().split('T')[0];
  if (predictionEndDate) predictionEndDate.value = nextWeekStr;

  // 店舗データの読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      const storeSelect = container.querySelector('#store-select');
      if (stores && storeSelect) {
        stores.forEach(store => {
          if (store.有効フラグ) {
            const option = document.createElement('option');
            option.value = store.店舗ID;
            option.textContent = `${store.店舗コード} - ${store.店舗名}`;
            storeSelect.appendChild(option);
          }
        });
      }
    } catch (error) {
      window.aivicNotify.error('店舗データの読み込みに失敗しました: ' + error.message);
    }
  }

  // 商品カテゴリの読み込み
  async function loadProductCategories() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      const categoryContainer = container.querySelector('#category-checkboxes');
      if (products && categoryContainer) {
        const categories = [...new Set(products.map(p => p.商品カテゴリID).filter(Boolean))];
        categories.forEach(categoryId => {
          const label = document.createElement('label');
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.value = categoryId;
          checkbox.name = 'product-categories';
          label.appendChild(checkbox);
          label.appendChild(document.createTextNode(`カテゴリ ${categoryId.substring(0, 8)}`));
          categoryContainer.appendChild(label);
        });
      }
    } catch (error) {
      window.aivicNotify.error('商品カテゴリの読み込みに失敗しました: ' + error.message);
    }
  }

  // スライダーの値更新
  function setupSliders() {
    const sliders = ['spring', 'summer', 'autumn', 'winter'];
    sliders.forEach(season => {
      const slider = container.querySelector(`#${season}-weight`);
      const display = container.querySelector(`#${season}-weight-display`);
      if (slider && display) {
        slider.addEventListener('input', function() {
          display.textContent = this.value + '%';
        });
        display.textContent = slider.value + '%';
      }
    });
  }

  // 学習データ収集処理
  async function handleDataCollection() {
    try {
      const storeId = container.querySelector('#store-select')?.value;
      const startDate = container.querySelector('#learning-start-date')?.value;
      const endDate = container.querySelector('#learning-end-date')?.value;

      if (!storeId || !startDate || !endDate) {
        window.aivicNotify.error('必要な項目を入力してください');
        return;
      }

      // 売上データ収集
      const salesData = await collectSalesData(storeId, startDate, endDate);

      // 商品別分類
      const productClassified = classifySalesDataByProduct(salesData);

      // 店舗別分類
      const storeClassified = classifySalesDataByStore(salesData);

      // 有効データフィルタリング
      const validData = filterValidProductData(productClassified);

      // 天気データ収集
      const weatherData = await collectWeatherData(startDate, endDate);

      // イベントデータ収集
      const eventData = await collectEventData(startDate, endDate);

      // 季節データ収集
      const seasonalData = collectSeasonalData(startDate, endDate);

      // 結果表示
      const resultArea = container.querySelector('#collection-result');
      if (resultArea) {
        resultArea.innerHTML = `
          <h4>データ収集完了</h4>
          <p>売上データ: ${salesData.length}件</p>
          <p>有効商品データ: ${validData.length}件</p>
          <p>天気データ: ${weatherData.length}件</p>
          <p>イベントデータ: ${eventData.length}件</p>
        `;
      }

      window.aivicNotify.success('データ収集が完了しました');

    } catch (error) {
      window.aivicNotify.error('データ収集に失敗しました: ' + error.message);
    }
  }

  // 相関分析処理
  async function handleCorrelationAnalysis() {
    try {
      const storeId = container.querySelector('#store-select')?.value;
      const startDate = container.querySelector('#learning-start-date')?.value;
      const endDate = container.querySelector('#learning-end-date')?.value;

      if (!storeId || !startDate || !endDate) {
        window.aivicNotify.error('必要な項目を入力してください');
        return;
      }

      // データ収集
      const salesData = await collectSalesData(storeId, startDate, endDate);
      const weatherData = await collectWeatherData(startDate, endDate);
      const eventData = await collectEventData(startDate, endDate);
      const seasonalData = collectSeasonalData(startDate, endDate);

      // 相関分析実行
      const weatherCorr = analyzeCorrelationSalesWeather(salesData, weatherData);
      const eventCorr = analyzeCorrelationSalesEvent(salesData, eventData);
      const seasonCorr = analyzeCorrelationSalesSeason(salesData, seasonalData);

      // 結果表示
      const resultArea = container.querySelector('#correlation-result');
      if (resultArea) {
        resultArea.innerHTML = `
          <h4>相関分析結果</h4>
          <p>天気との相関: ${weatherCorr.correlation?.toFixed(3) || 'N/A'}</p>
          <p>イベントとの相関: ${eventCorr.correlation?.toFixed(3) || 'N/A'}</p>
          <p>季節との相関: ${seasonCorr.correlation?.toFixed(3) || 'N/A'}</p>
        `;
      }

      window.aivicNotify.success('相関分析が完了しました');

    } catch (error) {
      window.aivicNotify.error('相関分析に失敗しました: ' + error.message);
    }
  }

  // 履歴比較処理
  async function handleHistoricalComparison() {
    try {
      const storeId = container.querySelector('#store-select')?.value;
      const startDate = container.querySelector('#learning-start-date')?.value;
      const endDate = container.querySelector('#learning-end-date')?.value;

      if (!storeId || !startDate || !endDate) {
        window.aivicNotify.error('必要な項目を入力してください');
        return;
      }

      // 期間検証
      const isValidPeriod = validateComparisonPeriod(startDate, endDate);
      if (!isValidPeriod) {
        window.aivicNotify.error('比較期間が無効です');
        return;
      }

      // 現在データ収集
      const currentData = await collectSalesData(storeId, startDate, endDate);

      // 履歴比較実行
      const comparisonResult = await compareWithHistoricalData(currentData, storeId);

      // 代替比較データ検索
      const alternativeData = await findAlternativeComparisonData(storeId, startDate, endDate);

      // 結果表示
      const resultArea = container.querySelector('#comparison-result');
      if (resultArea) {
        resultArea.innerHTML = `
          <h4>履歴比較結果</h4>
          <p>比較データ件数: ${comparisonResult.historicalCount || 0}件</p>
          <p>成長率: ${comparisonResult.growthRate?.toFixed(2) || 'N/A'}%</p>
          <p>代替データ: ${alternativeData.length}件</p>
        `;
      }

      window.aivicNotify.success('履歴比較が完了しました');

    } catch (error) {
      window.aivicNotify.error('履歴比較に失敗しました: ' + error.message);
    }
  }

  // 需要予測実行処理
  async function handlePredictionExecution() {
    try {
      const storeId = container.querySelector('#store-select')?.value;
      const predStartDate = container.querySelector('#prediction-start-date')?.value;
      const predEndDate = container.querySelector('#prediction-end-date')?.value;
      const learningStartDate = container.querySelector('#learning-start-date')?.value;
      const learningEndDate = container.querySelector('#learning-end-date')?.value;

      if (!storeId || !predStartDate || !predEndDate || !learningStartDate || !learningEndDate) {
        window.aivicNotify.error('必要な項目を入力してください');
        return;
      }

      // 選択されたカテゴリ取得
      const selectedCategories = Array.from(container.querySelectorAll('input[name="product-categories"]:checked'))
        .map(cb => cb.value);

      // 季節重み取得
      const seasonWeights = {
        spring: parseInt(container.querySelector('#spring-weight')?.value || 25),
        summer: parseInt(container.querySelector('#summer-weight')?.value || 25),
        autumn: parseInt(container.querySelector('#autumn-weight')?.value || 25),
        winter: parseInt(container.querySelector('#winter-weight')?.value || 25)
      };

      // 学習データ収集
      const salesData = await collectSalesData(storeId, learningStartDate, learningEndDate);
      const weatherData = await collectWeatherData(learningStartDate, learningEndDate);
      const eventData = await collectEventData(learningStartDate, learningEndDate);
      const seasonalData = collectSeasonalData(learningStartDate, learningEndDate);

      // 予測期間の外部データ収集
      const futureWeatherData = await collectWeatherData(predStartDate, predEndDate);
      const futureEventData = await collectEventData(predStartDate, predEndDate);
      const futureSeasonalData = collectSeasonalData(predStartDate, predEndDate);

      // 相関分析
      const weatherCorr = analyzeCorrelationSalesWeather(salesData, weatherData);
      const eventCorr = analyzeCorrelationSalesEvent(salesData, eventData);
      const seasonCorr = analyzeCorrelationSalesSeason(salesData, seasonalData);

      // 簡易予測計算（実際のAIモデルの代替）
      const avgDailySales = salesData.reduce((sum, item) => sum + (item.売上数量 || 0), 0) / salesData.length;
      const weatherImpact = (weatherCorr.correlation || 0) * 0.1;
      const eventImpact = (eventCorr.correlation || 0) * 0.15;
      const seasonImpact = (seasonCorr.correlation || 0) * 0.2;

      const predictionDays = Math.ceil((new Date(predEndDate) - new Date(predStartDate)) / (1000 * 60 * 60 * 24));
      const totalPrediction = Math.round(avgDailySales * predictionDays * (1 + weatherImpact + eventImpact + seasonImpact));

      // 結果表示
      const resultArea = container.querySelector('#prediction-result');
      if (resultArea) {
        resultArea.innerHTML = `
          <h4>需要予測結果</h4>
          <p>予測期間: ${predStartDate} ～ ${predEndDate}</p>
          <p>予測総需要量: ${totalPrediction}個</p>
          <p>1日平均予測: ${Math.round(totalPrediction / predictionDays)}個</p>
          <p>天気影響度: ${(weatherImpact * 100).toFixed(1)}%</p>
          <p>イベント影響度: ${(eventImpact * 100).toFixed(1)}%</p>
          <p>季節影響度: ${(seasonImpact * 100).toFixed(1)}%</p>
        `;
      }

      // 予測結果をデータベースに保存
      const predictionRecord = {
        店舗ID: storeId,
        予測開始日: predStartDate,
        予測終了日: predEndDate,
        予測総需要量: totalPrediction,
        天気相関: weatherCorr.correlation,
        イベント相関: eventCorr.correlation,
        季節相関: seasonCorr.correlation,
        作成日時: new Date().toISOString()
      };

      await window.aivicApi.save(5, predictionRecord); // 需要予測結果テーブル

      window.aivicNotify.success('需要予測が完了しました');

    } catch (error) {
      window.aivicNotify.error('需要予測に失敗しました: ' + error.message);
    }
  }

  // イベントハンドラー設定
  const collectDataBtn = container.querySelector('#collect-data-btn');
  if (collectDataBtn) {
    collectDataBtn.addEventListener('click', handleDataCollection);
  }

  const analyzeCorrelationBtn = container.querySelector('#analyze-correlation-btn');
  if (analyzeCorrelationBtn) {
    analyzeCorrelationBtn.addEventListener('click', handleCorrelationAnalysis);
  }

  const compareHistoryBtn = container.querySelector('#compare-history-btn');
  if (compareHistoryBtn) {
    compareHistoryBtn.addEventListener('click', handleHistoricalComparison);
  }

  const executePredictionBtn = container.querySelector('#execute-prediction-btn');
  if (executePredictionBtn) {
    executePredictionBtn.addEventListener('click', handlePredictionExecution);
  }

  // 初期化実行
  setupSliders();
  loadStores();
  loadProductCategories();
}
